from:
#screen-game {
  top: 0;
  bottom: 0;
  padding: 0;
  overflow: hidden;
  background: #0B0716
}

replace:
#screen-game {
  top: 0;
  bottom: 0;
  padding: 0;
  overflow: hidden;
  background: #0B0716
}

#screen-game.active {
  display: flex;
  flex-direction: column
}

#app:fullscreen #hdr,
#app:fullscreen #tabbar,
#app:fullscreen .screen:not(#screen-game) {
  max-width: 680px;
  margin-left: auto;
  margin-right: auto;
  left: 0;
  right: 0
}

#app:fullscreen .sheet {
  max-width: 640px;
  margin-left: auto;
  margin-right: auto
}

#app.in-game #hdr,
#app.in-game #tabbar {
  display: none
}

/* ============ GAME ============ */
#stageWrap {
  position: relative;
  flex: 1;
  width: 100%;
  min-height: 0;
  overflow: hidden;
  background: #0B0716
}

#cv {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none
}

#gameOverlayFx {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(255, 255, 255, .012) 0 1px, transparent 1px 4px), radial-gradient(ellipse at 50% 45%, transparent 55%, rgba(5, 2, 12, .48) 100%)
}

#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  transition: box-shadow .4s
}

#vignette.danger {
  animation: dangerpulse 1.1s ease-in-out infinite
}

@keyframes dangerpulse {
  0%,
  100% {
    box-shadow: inset 0 0 70px rgba(255, 77, 94, .12)
  }
  50% {
    box-shadow: inset 0 0 120px rgba(255, 77, 94, .34)
  }
}

#hud {
  position: relative;
  flex: none;
  width: 100%;
  padding: calc(env(safe-area-inset-top, 0px) + 7px) 12px 7px;
  background: linear-gradient(180deg, rgba(14, 9, 28, .98), rgba(11, 7, 22, .92));
  border-bottom: 1px solid var(--line2);
  z-index: 10;
  box-shadow: 0 4px 18px rgba(3, 1, 10, .55)
}

.hud-inner {
  max-width: 680px;
  margin: 0 auto
}

.hud-top {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 8px;
  align-items: center
}

#hud .btn-icon,
#hud .mute-btn,
#hud .fs-btn,
#hud .chip-btn {
  pointer-events: auto
}

.hud-left {
  display: flex;
  gap: 6px;
  align-items: center
}

.hud-mid {
  text-align: center;
  min-width: 0
}

#hudLevel {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.6px;
  color: var(--muted);
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis
}

#hudScore {
  font-family: var(--font-d);
  font-weight: 900;
  font-size: 23px;
  line-height: 1.08;
  color: #fff;
  text-shadow: 0 0 16px rgba(139, 92, 246, .8)
}

body.large-hud #hudLevel {
  font-size: 12px
}

body.large-hud #hudScore {
  font-size: 28px
}

#hudTimer {
  font-size: 11px;
  font-weight: 800;
  color: var(--amber);
  display: none
}

#hudTimer.show {
  display: block
}

.hud-right {
  display: flex;
  align-items: center;
  gap: 6px
}

.hud-right-row {
  display: flex;
  gap: 5px
}

#hud .mute-btn .m-label {
  display: none
}

.hud-coins {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  font-weight: 800;
  color: #FFC53D;
  background: rgba(20, 12, 34, .82);
  border: 1px solid rgba(255, 197, 61, .35);
  padding: 5px 9px;
  border-radius: 999px
}

.hud-sub {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 7px;
  margin-top: 5px;
  flex-wrap: wrap;
  min-height: 22px
}

.hud-sub-left {
  display: flex;
  align-items: center;
  gap: 7px;
  flex-wrap: wrap
}

#hudLives {
  display: flex;
  gap: 3px;
  font-size: 14px
}

#hudLives .ic {
  color: var(--danger)
}

#hudLives .ic svg {
  fill: currentColor
}

#hudLives .ic.empty {
  color: #3A3160
}

#hudLives .ic.empty svg {
  fill: none
}

#hudCombo {
  display: none;
  align-items: center;
  gap: 6px;
  background: rgba(255, 61, 138, .14);
  border: 1px solid rgba(255, 61, 138, .5);
  border-radius: 999px;
  padding: 2px 9px;
  font-family: var(--font-d);
  font-weight: 800;
  font-size: 11.5px;
  color: var(--magenta);
  position: relative;
  overflow: hidden
}

#hudCombo.show {
  display: inline-flex
}

#comboBar {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2.5px;
  background: var(--magenta)
}

#hudFx {
  display: flex;
  gap: 4px;
  flex-wrap: wrap
}

.fx-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 999px;
  background: rgba(20, 12, 34, .85);
  border: 1px solid var(--fc, #22D3EE);
  color: var(--fc, #22D3EE);
  position: relative;
  overflow: hidden
}

.fx-chip .fx-bar {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2.5px;
  background: var(--fc)
}

#boostBar {
  display: none;
  margin-top: 5px;
  padding-top: 5px;
  border-top: 1px solid rgba(160, 140, 255, .1);
  pointer-events: auto
}

#boostBar.show {
  display: flex;
  align-items: center;
  gap: 7px
}

#boostBar .bb-label {
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 1.2px;
  color: var(--faint);
  white-space: nowrap;
  flex: none
}

#boostBar .bb-row {
  display: flex;
  gap: 5px;
  overflow-x: auto;
  flex: 1;
  scrollbar-width: none
}

#boostBar .bb-row::-webkit-scrollbar {
  display: none
}

.chip-btn {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 10.5px;
  font-weight: 800;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(29, 20, 52, .9);
  border: 1px solid var(--line2);
  color: var(--text)
}

.chip-btn:active {
  transform: scale(.94)
}

.chip-btn.armed {
  color: #0B0716;
  background: var(--grad-acid);
  border-color: transparent
}

#fpsBadge {
  position: absolute;
  top: 8px;
  right: 10px;
  background: rgba(11, 7, 22, .78);
  border: 1px solid var(--line2);
  color: var(--lime);
  font-family: monospace;
  font-size: 10.5px;
  font-weight: 700;
  padding: 3px 7px;
  border-radius: 7px;
  pointer-events: none;
  z-index: 12;
  display: none
}

#fpsBadge.show {
  display: block
}

#gameHint {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  bottom: calc(env(safe-area-inset-bottom, 0px) + 12px);
  background: rgba(16, 10, 32, .88);
  border: 1px solid var(--line2);
  color: var(--text);
  font-size: 11.5px;
  font-weight: 600;
  padding: 5px 14px;
  border-radius: 999px;
  pointer-events: none;
  white-space: nowrap;
  transition: opacity .35s;
  z-index: 10;
  box-shadow: 0 4px 16px rgba(0, 0, 0, .5)
}

#gameHint.hide {
  opacity: 0
}

